package cl.acis.ordenes.service;
import cl.acis.ordenes.dto.*; import cl.acis.ordenes.exception.*; import cl.acis.ordenes.model.*; import cl.acis.ordenes.repository.*; import org.junit.jupiter.api.*; import org.mockito.*; import java.time.*; import java.util.*; import static org.junit.jupiter.api.Assertions.*; import static org.mockito.ArgumentMatchers.*; import static org.mockito.Mockito.*;
class OrdenServiceTest { @Mock OrdenRepository repo; @Mock EventoOrdenRepository eventos; OrdenService service; @BeforeEach void init(){MockitoAnnotations.openMocks(this);service=new OrdenService(repo,eventos,new ReglasOrden());when(repo.save(any())).thenAnswer(i->i.getArgument(0));when(eventos.save(any())).thenAnswer(i->i.getArgument(0));}
 @Test void crearGeneraCodigoYSla(){when(repo.findTopByOrderByIdDesc()).thenReturn(Optional.empty());OrdenResponse r=service.crear(new OrdenRequest(5L,null,"Mantención",Prioridad.ALTA,LocalDateTime.now().plusDays(1),"Descripción",null),1L);assertEquals("OT-0001",r.codigo());assertEquals(8,r.slaHoras());verify(eventos).save(any(EventoOrden.class));}
 @Test void checkOutExigeFoto(){OrdenTrabajo o=new OrdenTrabajo();o.setEstado(EstadoOrden.EN_EJECUCION);o.setTecnicoId(3L);when(repo.findById(1L)).thenReturn(Optional.of(o));AccionRequest r=new AccionRequest(AccionOrden.CHECK_OUT,null,null,null,null,null,"diag","actividad","mat",0);assertThrows(ReglaNegocioException.class,()->service.accion(1L,r,"TECNICO",3L));}
 @Test void tecnicoSoloPuedeAceptarSuOrden(){OrdenTrabajo o=new OrdenTrabajo();o.setEstado(EstadoOrden.ASIGNADA);o.setTecnicoId(3L);when(repo.findById(1L)).thenReturn(Optional.of(o));OrdenResponse r=service.accion(1L,new AccionRequest(AccionOrden.ACEPTAR,null,null,null,null,null,null,null,null,null),"TECNICO",3L);assertEquals(EstadoOrden.ACEPTADA,r.estado());}
 @Test void asignarRechazaSextaOrden(){OrdenTrabajo o=new OrdenTrabajo();o.setEstado(EstadoOrden.CREADA);o.setFechaProgramada(LocalDateTime.now().plusDays(1));when(repo.findById(1L)).thenReturn(Optional.of(o));when(repo.countByTecnicoIdAndFechaProgramadaBetween(anyLong(),any(),any())).thenReturn(6L);assertThrows(ReglaNegocioException.class,()->service.accion(1L,new AccionRequest(AccionOrden.ASIGNAR,"",null,3L,null,null,null,null,null,null),"JEFATURA",1L));}
}
